    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "day" => Some(Self::Day),
            "12h" => Some(Self::HalfDay),
            "4h" => Some(Self::FourHours),
            "2h" => Some(Self::TwoHours),
            "1h" => Some(Self::OneHour),
            _ => None,
        }
    }
}

